// DeleteSecretInstanceCmd represents the command 'tptctl delete secret-instance'
var DeleteSecretInstanceCmd = &cobra.Command{
	Aliases: []string{secretInstanceShortAlias},
	Example: "  # delete using a config file\n  tptctl delete secret-instance --config path/to/config.yaml\n\n  # delete using name\n  tptctl delete secret-instance --name some-secret-instance",
	Long:    "Delete an existing secret instance.",
	PreRun:  CommandPreRunFunc,
	Run: func(cmd *cobra.Command, args []string) {
		apiClient, _, apiEndpoint, _ := GetClientContext(cmd)

		// flag validation
		if err := cli.ValidateConfigNameFlags(
			secretConfigPath,
			secretName,
			"secret instance",
		); err != nil {
			cli.Error("flag validation failed", err)
			os.Exit(1)
		}

		// delete secret instance based on version
		switch secretVersion {
		case "v0":
			var secretInstanceConfig config_v0.SecretInstanceConfig
			if secretConfigPath != "" {
				// load secret instance config
				configContent, err := cli.ReadConfigContent(secretConfigPath, secretStdin)
				if err != nil {
					cli.Error("failed to read config", err)
					os.Exit(1)
				}
				if err := yaml.UnmarshalStrict(configContent, &secretInstanceConfig); err != nil {
					cli.Error("failed to unmarshal config file yaml content", err)
					os.Exit(1)
				}
			} else {
				secretInstanceConfig = config_v0.SecretInstanceConfig{
					SecretInstance: config_v0.SecretInstanceValues{
						Name: &secretName,
					},
				}
			}

			// delete secret instance
			secretInstanceConfig.SecretInstance.SecretConfigPath = &secretConfigPath
			deletedSecretInstance, err := secretInstanceConfig.Delete(apiClient, apiEndpoint)
			if err != nil {
				cli.Error("failed to delete secret instance", err)
				os.Exit(1)
			}

			cli.Complete(fmt.Sprintf("secret instance %s deleted", *deletedSecretInstance.SecretInstance.Name))
		default:
			cli.Error("", errors.New("unrecognized object version"))
			os.Exit(1)
		}
	},
	Short:        "Delete an existing secret instance",
	SilenceUsage: true,
	Use:          "secret-instance",
}

func init() {
	DeleteCmd.AddCommand(DeleteSecretInstanceCmd)

	DeleteSecretInstanceCmd.Flags().StringVarP(
		&secretConfigPath,
		"config", "c", "", "Path to file with secret instance config.",
	)
	DeleteSecretInstanceCmd.Flags().StringVarP(
		&secretName,
		"name", "n", "", "Name of secret instance.",
	)
	DeleteSecretInstanceCmd.Flags().StringVarP(
		&cliArgs.ControlPlaneName,
		"control-plane-name", "i", "", "Optional. Name of control plane. Will default to current control plane if not provided.",
	)
	DeleteSecretInstanceCmd.Flags().StringVarP(
		&secretVersion,
		"version", "v", "v0", "Version of secret instances object to delete. One of: [v0]",
	)
}
